def links(items):
    return '<div class="links">'+''.join(f'<a href="{escape(url,quote=True)}">{escape(label)}</a>' for label,url in items)+'</div>'

def page(route,title,body,active='',article=False):
    p=OUT/route.strip('/')/'index.html' if route!='/' else OUT/'index.html'
    p.parent.mkdir(parents=True,exist_ok=True)
    nav=''.join(f'<a href="{url}"'+(' aria-current="page"' if active==label else '')+f'>{label}</a>' for label,url in [('Home','/'),('Projects','/projects/'),('Research','/research/'),('Notes','/notes/'),('About','/about/')])
    p.write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)} | Renchi Zhang</title><meta name="description" content="{escape(title,quote=True)}. Research, robotic systems and experiments by Renchi Zhang."><link rel="alternate" hreflang="en" href="{route}"><link rel="alternate" hreflang="zh-CN" href="/zh{route}"><script src="/theme.js"></script><link rel="stylesheet" href="/style.css"></head><body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="/"><span class="site-mark" aria-hidden="true">rz</span><span class="site-label">/ {active.lower()}</span></a><nav aria-label="Main navigation">{nav}</nav><div class="display-controls" aria-label="Display preferences"><a class="language-switch" href="/zh{route}" hreflang="zh-CN" lang="zh" aria-label="Switch to Chinese">中文</a><button type="button" class="theme-toggle" data-theme-toggle hidden aria-label="Switch to dark mode">dark</button></div></header><main id="main">{'<article class="article">' if article else ''}{body}{'</article>' if article else ''}</main><footer><span>Renchi Zhang · Robotics &amp; human–AI interaction</span><span><a href="mailto:renchi.rz.zhang@gmail.com">Email</a> · <a href="{GITHUB}">GitHub</a> · <a href="{SCHOLAR}">Scholar</a></span><span class="life-teaser"><span data-life-message>do not press this button</span><button type="button" class="life-egg-button" data-life-trigger data-egg-stage="0" aria-label="Do not press this button"><span aria-hidden="true">!</span></button></span></footer></body></html>''')

