notes='''<div class="note"><small>Essay · draft</small><div><h3><a href="/notes/why-i-build-robots/">Why I still build robots for humans</a></h3></div></div><div class="note"><small>Concept · draft</small><div><h3><a href="/notes/fast-slow-embodied-agents/">System 1, System 2, and embodied agents</a></h3></div></div><div class="note"><small>Experiment · planned</small><div><h3><a href="/notes/research-loop/">Can an AI scientist improve its experimental strategy?</a></h3></div></div>'''
page('/','Renchi Zhang','''<div class="intro"><div class="intro-heading"><div><h1>Renchi Zhang <span lang="zh">张任驰</span></h1><p class="affiliation">PhD candidate · Cognitive Robotics · TU Delft</p></div><img class="pixel-mascot" src="/assets/pixel-chess-arm.png" width="120" height="120" alt="Pixel-art robot arm holding a blue chess pawn"></div><p>I build robots and study how people work with them. My PhD explores where humans and AI differ in perception, reasoning and action, through real robotic systems and controlled experiments.</p><p>I’m interested in embodied intelligence, human–AI complementarity, and how an agent can learn from its own failures. I like building things that people can actually use.</p>'''+links([('email','mailto:renchi.rz.zhang@gmail.com'),('scholar',SCHOLAR),('github',GITHUB),('cv','/assets/Renchi_Zhang_CV.pdf')])+'''<p class="caption">PhD defence: 14 September 2026</p></div><section class="section"><div class="section-head"><h2>Selected research</h2><a href="/research/">all publications</a></div>'''+cards+'''</section><section class="section"><h2>Now</h2><p>I’m exploring VLA post-training and designing an <a href="/notes/research-loop/">experiment on scientific agents</a>: can a system use what went wrong to choose a better experiment next?</p></section><section class="section"><h2>Writing &amp; notes</h2>'''+notes+'</section>','Home')
page('/projects/','Projects','''<p class="eyebrow">Systems &amp; experiments</p><h1>Projects</h1><p class="lead">My work connects functioning robotic systems with controlled evaluation and real human interaction.</p><section class="section">'''+cards+'''</section><section class="section"><h2>Current directions</h2><div class="two"><div><h3>VLA post-training</h3><p>LoRA fine-tuning of GR00T N1.6 and robustness evaluation under changed language and scene appearance. Work to date is offline; robot deployment remains a next step.</p><span class="tag">In progress · Since April 2026</span></div><div><h3>Scientific agent loops</h3><p>Designing a controlled comparison of fixed experimental plans, adaptive iteration and structured memory, followed by a test of strategy transfer.</p><a href="/notes/research-loop/">Read the proposal</a></div></div></section>''','Projects')
page('/projects/openchessrobot/','OpenChessRobot','''<p class="eyebrow">Robotic system · 2022–2025</p><h1>OpenChessRobot</h1><p class="lead">An open-source chess robot for studying how people interact with a system that sees, acts and explains.</p>'''+links([('Paper','https://doi.org/10.3389/frobt.2025.1436674'),('Code',GITHUB+'/OpenChessRobot')])+'''<figure class="video-figure"><video class="project-video" controls playsinline preload="metadata" poster="/assets/video/openchessrobot.jpg" aria-label="OpenChessRobot demonstration video"><source src="/assets/video/openchessrobot.mp4" type="video/mp4"></video><figcaption>OpenChessRobot plays and comments on a chess position.</figcaption></figure><figure><img class="wide-photo" src="/assets/chess-system.png" alt="OpenChessRobot hardware with Franka Panda arm, chessboard and sensing system"><figcaption>System hardware. Source: thesis Chapter 4, Figure 4.1B.</figcaption></figure><figure><img class="wide-photo" src="/assets/chess-demo.png" alt="Visitors playing chess with OpenChessRobot at a demonstration"><figcaption>OpenChessRobot at a demonstration. Thesis Chapter 4, Figure 4.1A.</figcaption></figure><h2>The problem</h2><p>To study interaction with an intelligent robot, people need a system they can actually use. Chess supplies a rich but verifiable setting: the board state, legal moves and engine evaluation can be checked independently of the robot’s spoken explanation.</p><h2>What I built</h2><p>The system combines a Franka Panda arm, ZED2 camera, learned piece recognition, chess-state validation, Stockfish, MoveIt motion planning and LLM-generated spoken commentary. ROS connects the modules, and an open hardware design includes a gripper adapted to the chess pieces.</p><p>Recognition alone is insufficient. The perceived board is checked against chess rules and the previous state before execution. An illegal state triggers another observation from a shifted camera pose. The language model provides commentary; Stockfish supplies the move decision.</p><h2>What the evaluation showed</h2><p>The study combined component evaluation, a 597-person scenario survey and a FIDE Master case study. The robot provided a reproducible interaction platform, while the expert assessment exposed a gap between fluent commentary and strategic depth.</p><div class="callout"><p><strong>Research takeaway:</strong> a system can appear coherent at the interface while one part of its reasoning remains shallow. Evaluation needs to distinguish perception, action and explanation quality.</p></div><h2>Where this leads</h2><p>This platform motivates my next question: can a robot turn a failure into a testable diagnosis, then use the evidence to select a better intervention?</p>''','Projects',True)
page('/projects/visual-search/','Human and MLLM visual search','''<p class="eyebrow">Controlled evaluation · Perception</p><h1>Human-like attention?</h1><p class="lead">A psychophysical comparison of visual search in humans and multimodal large language models.</p>'''+links([('Paper','https://doi.org/10.1007/s42113-026-00333-4'),('Code',GITHUB+'/MLLM-Visual-Search'),('Study website','https://renchizhhhh.github.io/mllm_visual_search_site/')])+'''<figure><img src="/assets/visual-search.png" alt="Examples of 3D visual-search scenes containing geometric objects of different colours, shapes and sizes"><figcaption>Example 3D stimuli from thesis Chapter 2, Figure 2.1.</figcaption></figure><h2>Design</h2><p>Nine conditions vary feature versus conjunction search, distractor heterogeneity, and 2D versus 3D presentation. The study recruited 1,250 people and retained 157,042 human trials for analysis. Three MLLMs were evaluated on 6,300 synthetic images.</p><h2>Finding</h2><p>Across 18 condition summaries, model error rates correlated with human response times (Spearman ρ = 0.91) and human error rates (ρ = 0.82). Yet difficult conjunction scenes produced strongly biased model responses. Humans instead showed changes in response time and accuracy.</p><div class="callout"><p><strong>Interpretation:</strong> agreement in difficulty rankings can coexist with different failure patterns. The results support behavioural diagnosis; they do not, by themselves, identify the models’ internal mechanisms.</p></div><h2>Connection to robotics</h2><p>A human supervisor may assume that a model sees a scene as they do. Testing specific combinations of visual features helps expose where that assumption breaks down. Transfer from these synthetic scenes to real robot perception remains a research question.</p>''','Projects',True)
page('/projects/interactive-platforms/','Interactive and educational platforms','''<p class="eyebrow">Real interaction · Experimental platforms</p><h1>Learning and working with Spot</h1><p class="lead">Two complementary platforms: directing a mobile robot, and learning to verify LLM-generated plans.</p><h2 id="walk-along">Walk along with Spot</h2><p>In a 2 × 2 within-subject experiment, 218 operators controlled Spot using voice or gestures while standing or walking alongside it. HoloLens 2 supplied speech and hand-tracking inputs to the robot interface. The study included 872 real-robot trials.</p><p>Voice with walking was the most favoured combination. Gesture control while standing caused more left/right confusion, showing how physical position and command modality affect interaction.</p>'''+links([('Paper','https://doi.org/10.1145/3729540'),('Code',GITHUB+'/Walk-along-Spot')])+'''<figure class="video-figure"><video class="project-video" controls playsinline preload="metadata" poster="/assets/video/walk-along-spot.jpg" aria-label="Walk-along Spot experiment video"><source src="/assets/video/walk-along-spot.mp4" type="video/mp4"></video><figcaption>Three views of voice and gesture control while walking with Spot.</figcaption></figure><h2 id="llm-workshop">LLM robotics workshop</h2><p>A mobile web interface lets students submit navigation prompts and inspect plans, trajectories and rule-based penalties. Ten workshop sessions involved 226 students and culminated in live Spot demonstrations. Of 494 consented prompts, 457 entered the reported plan evaluation; 200 students provided the analysed questionnaire responses.</p><p>On Task 1, the reasoning-model condition achieved 55.7% penalty-free plans, compared with 18.7% in the non-reasoning condition. The reasoning condition fell to 21.6% on Task 3. Students changed their prompting strategies across conditions.</p><p>The workshop supports studying how people allocate work between themselves and an AI system. Reported learning is self-reported; the study did not establish long-term retention or isolate reasoning as an architectural cause of the model differences.</p>'''+links([('Manuscript','https://www.researchgate.net/publication/401246763_Educating_future_engineers_about_LLMs_A_scalable_workshop'),('Code',GITHUB+'/LLM-robotics-workshop')])+'''<figure class="video-figure"><video class="project-video" controls playsinline preload="metadata" poster="/assets/video/llm-robotics-workshop.jpg" aria-label="LLM robotics workshop demonstration video"><source src="/assets/video/llm-robotics-workshop.mp4" type="video/mp4"></video><figcaption>From a natural-language prompt and simulated plan to execution on Spot.</figcaption></figure><div class="callout"><p><strong>Shared principle:</strong> make the consequences of human instructions and AI decisions visible enough to inspect, discuss and measure.</p></div>''','Projects',True)

pubs=[('2026','Human-like attention? A psychophysical comparison of visual search in humans and MLLMs.','Zhang, R., de Winter, J. C. F., Dodou, D., Seyffert, H., & Eisma, Y. B.','Computational Brain & Behavior','https://doi.org/10.1007/s42113-026-00333-4','MLLM-Visual-Search'),('2025','Walk along: An experiment on controlling the mobile robot ‘Spot’ with voice and gestures.','Zhang, R.*, van der Linden, J.*, Dodou, D., Seyffert, H., Eisma, Y. B., & de Winter, J. C. F. (* Equal contribution.)','ACM Transactions on Human-Robot Interaction, 14(4), Article 64','https://doi.org/10.1145/3729540','Walk-along-Spot'),('2025','An open-source reproducible chess robot for human-robot interaction research.','Zhang, R., de Winter, J. C. F., Dodou, D., Seyffert, H., & Eisma, Y. B.','Frontiers in Robotics and AI, 12, Article 1436674','https://doi.org/10.3389/frobt.2025.1436674','OpenChessRobot'),('2024','A review on machine learning in flexible surgical and interventional robots.','Wu, D.*, Zhang, R.*, Pore, A., et al. (* Equal contribution.)','Biomedical Signal Processing and Control, 93, Article 106179','https://doi.org/10.1016/j.bspc.2024.106179',None),('2026','Educating future engineers about LLMs: A scalable workshop.','Zhang, R., de Winter, J. C. F., Dicke, T., Dodou, D., & Eisma, Y. B.','Manuscript submitted for publication','https://www.researchgate.net/publication/401246763_Educating_future_engineers_about_LLMs_A_scalable_workshop','LLM-robotics-workshop')]
